{
  "understanding": {
    "purpose": "展示各组件在 v1.x、v2.x 和 v3.x 中的支持情况，并说明版本限制、行为变化和迁移注意事项。",
    "reading": "读者先按组件定位行，再横向比较三个版本的支持状态，最后查看说明；也可能纵向扫描某个版本，寻找不支持或部分支持的组件。",
    "groups": [
      "第 2–4 列都是版本支持状态，承担相同的比较任务，宜保持一致宽度。",
      "第 1 列标识组件，第 5 列解释兼容条件；两者共同提供理解每行状态所需的上下文。"
    ],
    "keep_intact": [
      "支持状态及其符号，如“✓ 支持”“✕ 不支持”和“部分支持”，宜保持在一行。",
      "版本号、产品名、接口名和技术标识符应保持完整，包括说明中最长的不可断开字符串。",
      "组件名称宜尽量完整显示，以便快速定位行。"
    ],
    "may_wrap": [
      "说明中的中文句子可在自然位置换行；较长说明本来就会形成多行，可利用这些行高容纳其他单元格的换行。",
      "空间紧张时，较长组件名称可换行，但应保持词组和英文缩写易于辨认。"
    ]
  },
  "designs": [
    {
      "name": "A",
      "widths": [133, 83, 83, 83, 337],
      "idea": "优先让组件名称和版本状态保持单行，将剩余空间分配给说明，形成便于逐行比较的均衡布局。"
    },
    {
      "name": "B",
      "widths": [105, 83, 83, 83, 365],
      "idea": "允许较长组件名称换行，换取更宽的说明列，利用说明已有的多行高度容纳组件名称。"
    },
    {
      "name": "C",
      "widths": [133, 103, 103, 103, 277],
      "idea": "加宽三个等宽版本列以突出横向状态比较，同时保留完整的组件名称，让说明承担更多换行。"
    }
  ]
}
